WITH scoped AS (SELECT q.mktcode,q.tgtcode,q.bizdate,(q.lastPx/10000.0)*q.totalShare AS metric FROM `newzl`.`hsj_stock_hq_basic` q WHERE q.bizdate='2026-04-14' AND (EXISTS (SELECT 1 FROM `findsl_ext`.`scope_membership` s WHERE s.mktcode=q.mktcode AND s.tgtcode=q.tgtcode AND s.scope_code='000972' AND s.snapshot_id='csindex-2026-07-30-ba167bb7985c') AND ((q.mktcode=1 AND (q.tgtcode BETWEEN '600000' AND '600999' OR q.tgtcode BETWEEN '601000' AND '601999' OR q.tgtcode BETWEEN '603000' AND '603999' OR q.tgtcode BETWEEN '605000' AND '605999')) OR (q.mktcode=0 AND (q.tgtcode BETWEEN '000000' AND '000999' OR q.tgtcode BETWEEN '001000' AND '001999' OR q.tgtcode BETWEEN '002000' AND '002999' OR q.tgtcode BETWEEN '003000' AND '003999'))))), industry_stat AS (SELECT i.industry_code,AVG(s.metric) AS baseline FROM scoped s INNER JOIN `findsl_ext`.`industry_membership` i ON i.mktcode=s.mktcode AND i.tgtcode=s.tgtcode WHERE i.snapshot_id='baostock-industry-2026-07-13-4d38e6963e35' AND i.classification_system='证监会行业分类' AND i.industry_level='industry' GROUP BY i.industry_code) SELECT s.mktcode,s.tgtcode,s.bizdate FROM scoped s INNER JOIN `findsl_ext`.`industry_membership` i ON i.mktcode=s.mktcode AND i.tgtcode=s.tgtcode INNER JOIN industry_stat a ON a.industry_code=i.industry_code WHERE i.snapshot_id='baostock-industry-2026-07-13-4d38e6963e35' AND i.classification_system='证监会行业分类' AND i.industry_level='industry' AND s.metric>a.baseline;
